        const longestLine = t.split\('\\n'\).reduce\(\(max, l\) => Math.max\(max, l.length\), 0\);
        return { x: 0, y: 0, width: Math.max\(longestLine * 8, 50\), height: Math.max\(lines * 20, 20\) };
      };
