      proto = Object.getPrototypeOf\(proto\);
    }
  }
} catch\(e\) {}

function fixSvgDimensions\(raw\) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  for \(const m of raw.matchAll\(/transform="translate\\\(\\s*\([\\d.]+\)\\s*,\\s*\([\\d.]+\)\\s*\\\)"/g\)\) {
    const tx = parseFloat\(m[1]\), ty = parseFloat\(m[2]\);
    if \(isFinite\(tx\) && isFinite\(ty\)\) {
      minX = Math.min\(minX, tx\); minY = Math.min\(minY, ty\);
      maxX = Math.max\(maxX, tx\); maxY = Math.max\(maxY, ty\);
    }
  }
  for \(const m of raw.matchAll\(/<rect[^>]*?\\bx="\([\\d.-]+\)"[^>]*?\\by="\([\\d.-]+\)"[^>]*?\\bwidth="\([\\d.]+\)"[^>]*?\\bheight="\([\\d.]+\)"/g\)\) {
    const x = parseFloat\(m[1]\), y = parseFloat\(m[2]\), w = parseFloat\(m[3]\), h = parseFloat\(m[4]\);
    if \(isFinite\(x\) && isFinite\(y\) && w > 0 && h > 0\) {
      maxX = Math.max\(maxX, x + w\); maxY = Math.max\(maxY, y + h\);
    }
  }

  console.log\('  Bounds: minX=%d minY=%d maxX=%d maxY=%d', minX, minY, maxX, maxY\);

  if \(isFinite\(minX\) && isFinite\(maxX\)\) {
    const pad = 40;
    const extraW = 100, extraH = 80;
    const vbX = Math.min\(minX, 0\) - pad;
    const vbY = Math.min\(minY, 0\) - pad;
    const vbW = maxX - Math.min\(minX, 0\) + extraW + pad * 2;
    const vbH = maxY - Math.min\(minY, 0\) + extraH + pad * 2;
    console.log\('  New viewBox: %d %d %d %d', vbX, vbY, vbW, vbH\);

    let svg = raw
      .replace\(/viewBox="[^"]*"/, `viewBox="${vbX} ${vbY} ${vbW} ${vbH}"`\)
      .replace\(/style="[^"]*max-width:\\s*[\\d.]+px[^"]*"/, ''\)
      .replace\(/\\bwidth="[^"]*"/, 'width="100%"'\);
    svg = svg.replace\(/\(<svg[^>]*?\)\\bheight="[^"]*"/, '$1'\);
    if \(!svg.includes\('preserveAspectRatio'\)\) {
      svg = svg.replace\('<svg ', '<svg preserveAspectRatio="xMidYMid meet" '\);
    }
    return svg;
  }
  return raw;
}

