    A["duck-gen"] --> B["duck-gen-api-routes.d.ts"]
    A --> C["duck-gen-messages.d.ts"]
    B --> D["ApiRoutes\\\\nRouteReq\\\\nRouteRes\\\\nDuckClient"]
